// Deterministic demo data. The history is generated by running the REAL engine functions day by day,
// so every ledger (stock, journal, points, receivables, events) is consistent by construction.
import type { ChannelCode, DB, ID, Order, OrderStatus, Product } from './types';
import type { Ctx } from './core';
import { emptyDB, buildProducts, buildBoms, buildCustomers, buildPromotions, buildMappings } from './seedData';
import { addExpense, closePeriod, dr, cr, post } from './accounting';
import { adjustStock, closeTransferShort, createTransfer, onHand, postCount, receiveTransfer, startCount, reservedMap, bkey } from './inventory';
import { createPO, paySupplier, receiveGoods } from './purchasing';
import { createProductionOrder, recordProduction, completeProduction, versionAt, bomForProduct } from './bom';
import { advanceOrder, cancelOrder, createOrder, nextStatuses, resolveModifiers, returnOrder, NewOrderLine } from './orders';
import { importExternalOrder } from './channels';
import { createReceipt, createSettlement, customerOutstanding, receiveSettlement, settleable, submitSlip, rejectSlip, outstandingOrders, allocatedMap, orderBalance } from './payments';
import { adjustPoints, pointsBalance, redeemReward } from './loyalty';
import { claimNumber, createEvent, grantEntitlements, recordWinner, setEventStatus } from './events';
import { processPrintQueue } from './printing';
import { addDays, dayKey, mulberry32, r2, startOfDay } from '../lib/util';
import { CHANNELS, FLOWS } from './meta';
import { audit } from './core';

export const SEED_DAYS = 26;

export function buildSeed(now = new Date()): DB & { _seedErrors?: string[] } {
  const nowIso = now.toISOString();
  const d = emptyDB(nowIso) as DB & { _seedErrors?: string[] };
  d.products = buildProducts();
  d.boms = buildBoms(addDays(now, -SEED_DAYS - 3).toISOString());
  for (const b of d.boms) { const p = d.products.find((x) => x.id === b.productId)!; p.bomId = b.id; }
  d.customers = buildCustomers(nowIso);
  d.mappings = buildMappings(d.products);
  const rnd = mulberry32(20261113);
  const pick = <T,>(a: T[]) => a[Math.floor(rnd() * a.length)];
  const chance = (p: number) => rnd() < p;
  const int = (lo: number, hi: number) => lo + Math.floor(rnd() * (hi - lo + 1));
  const errors: string[] = [];
  const safe = (label: string, fn: () => void) => { try { fn(); } catch (e) { errors.push(`${label}: ${(e as Error).message}`); } };
  const P = (id: ID) => d.products.find((p) => p.id === id)!;
  const at = (off: number, h: number, m = 0) => { const x = startOfDay(addDays(now, off)); x.setHours(h, m, 0, 0); return x; };
  const cap = (x: Date) => (x.getTime() > now.getTime() - 60000 ? new Date(now.getTime() - 60000 * int(1, 40)) : x);
  const cx = (x: Date, userId = 'U1'): Ctx => ({ now: cap(x).toISOString(), userId, seed: true });

  // ---------- events & promotions
  const e0 = createEvent(d, cx(at(-SEED_DAYS - 2, 9)), { name: 'Lucky Draw – October 2026', description: 'Pick your lucky number on 3 boards.', boards: 3, min: 0, max: 99, reservationMinutes: 10, terms: 'One entitlement per ฿500 in a single bill. Winners announced on the 15th. Subject to applicable law.' });
  const e1 = createEvent(d, cx(at(-SEED_DAYS - 2, 9)), { name: 'Lucky Draw – November 2026', description: 'Spend ฿500 → pick a number on one of 3 boards (00–99).', boards: 3, min: 0, max: 99, reservationMinutes: 10, terms: 'One entitlement per ฿500 in a single bill (max 5). Numbers are first-come, first-served. Prize rules and legal terms must be approved before launch.' });
  d.promotions = buildPromotions(nowIso, e1);
  setEventStatus(d, cx(at(-SEED_DAYS - 1, 9)), e0, 'active');

  // opening capital
  const c0 = cx(at(-SEED_DAYS - 1, 8));
  post(d, c0, { memo: 'Owner capital contribution', refType: 'opening', lines: [dr('1100', 100000), dr('1110', 1900000), cr('3000', 2000000)] });

  // ---------- supply simulation helpers
  const dueInvoices: { invoiceId: ID; supplierId: ID; due: string }[] = [];
  const pendingTransfers: { id: ID; day: number }[] = [];
  const expiryDays: Record<string, number> = { M03: 12, M04: 60, M09: 90, M10: 20, M11: 30, R03: 120, R07: 150, F01: 120, F02: 90, F03: 90, F04: 45 };
  const modeOf = (p: Product, wh: ID) => (p.kind === 'finished' ? (wh === 'W3' ? 'produce' : 'transfer') : 'purchase');
  const unitStep = (p: Product) => (['kg', 'L'].includes(p.unit) ? 0.5 : 1);
  const roundUp = (q: number, p: Product) => Math.ceil(q / unitStep(p)) * unitStep(p);

  function replenish(off: number) {
    const c = cx(at(off, 6, 30), 'U8');
    for (const wh of ['W1', 'W2', 'W3']) {
      const bySup: Record<string, { productId: ID; qty: number; unitCost: number }[]> = {};
      for (const p of d.products) {
        const lv = p.levels[wh];
        if (!lv || modeOf(p, wh) !== 'purchase') continue;
        const bal = onHand(d, wh, p.id);
        if (bal < lv.min) {
          const drift = (p.id === 'M01' || p.id === 'M02' ? 1 + 0.0025 * (off + SEED_DAYS) : 1) * (0.98 + rnd() * 0.05);
          (bySup[p.supplierId!] ||= []).push({ productId: p.id, qty: roundUp(lv.max - bal, p), unitCost: r2(p.stdCost * drift) });
        }
      }
      for (const [sid, lines] of Object.entries(bySup)) {
        safe('purchase', () => {
          const poId = createPO(d, c, { supplierId: sid, warehouseId: wh, lines, expectedAt: c.now });
          const grn = receiveGoods(d, { ...c, now: at(off, 7, 15).toISOString() }, {
            poId, lines: lines.map((l) => { const p = P(l.productId); return { productId: l.productId, qty: l.qty, lot: p.trackLot ? `${p.sku.slice(-5)}-${dayKey(c.now).slice(5)}` : undefined, expiry: p.trackLot && expiryDays[p.id] ? addDays(c.now, expiryDays[p.id]).toISOString() : undefined }; }),
            freight: wh === 'W3' && sid === 'S1' ? 450 : 0, handling: 0, invoiceNo: `${d.suppliers.find((s) => s.id === sid)!.code}-${int(10000, 99999)}`,
          });
          const g = d.grns.find((x) => x.id === grn)!;
          const inv = d.apInvoices.find((i) => i.id === g.invoiceId)!;
          dueInvoices.push({ invoiceId: inv.id, supplierId: sid, due: inv.dueDate });
        });
      }
    }
    // production at the central roastery
    const w3 = (id: ID, units: number) => {
      const p = P(id);
      const bom = bomForProduct(d, id)!;
      const y = versionAt(bom, c.now)!.yieldQty;
      let batches = Math.max(1, Math.ceil(units / y));
      // never plan more batches than the components on hand allow
      for (const comp of versionAt(bom, c.now)!.components) batches = Math.min(batches, Math.floor(onHand(d, 'W3', comp.productId) / comp.qty + 1e-9));
      if (batches < 1) return;
      safe('production:' + id, () => {
        const po = createProductionOrder(d, { ...c, now: at(off, 8, 0).toISOString() }, { bomId: bom.id, plannedQty: batches * y, warehouseId: 'W3' });
        const total = batches * y;
        const wasteQty = id === 'F01' ? r2(total * 0.03) : id === 'F04' ? 1 : 0;
        recordProduction(d, { ...c, now: at(off, 9, 30).toISOString() }, po, { outputQty: r2(total - wasteQty), wasteQty });
        completeProduction(d, { ...c, now: at(off, 10, 0).toISOString() }, po);
        void p;
      });
    };
    for (const id of ['F01', 'F02', 'F03', 'F04']) {
      const lv = P(id).levels.W3;
      const bal = onHand(d, 'W3', id);
      if (bal < lv.min) w3(id, lv.max - bal);
    }
    // transfers from the hub to the stores
    for (const wh of ['W1', 'W2']) {
      const lines: { productId: ID; qty: number }[] = [];
      for (const p of d.products) {
        const lv = p.levels[wh];
        if (!lv || modeOf(p, wh) !== 'transfer') continue;
        const bal = onHand(d, wh, p.id);
        if (bal >= lv.min) continue;
        const reserved = reservedMap(d)[bkey('W3', p.id)] || 0;
        const avail = Math.max(0, onHand(d, 'W3', p.id) - reserved - p.levels.W3.min * 0.4);
        const q = Math.floor(Math.min(lv.max - bal, avail) / unitStep(p)) * unitStep(p);
        if (q > 0) lines.push({ productId: p.id, qty: q });
      }
      if (lines.length) safe('transfer', () => { const id = createTransfer(d, { ...c, now: at(off, 8, 30).toISOString() }, { fromWh: 'W3', toWh: wh, lines }); pendingTransfers.push({ id, day: off }); });
    }
  }

  function receivePending(off: number) {
    for (const t of [...pendingTransfers]) {
      if (t.day >= off) continue;
      pendingTransfers.splice(pendingTransfers.indexOf(t), 1);
      const tr = d.transfers.find((x) => x.id === t.id)!;
      safe('receive transfer', () => {
        const partial = chance(0.12) && tr.lines.length > 1;
        const c = cx(at(off, 8, 10), 'U7');
        receiveTransfer(d, c, t.id, tr.lines.map((l, i) => ({ productId: l.productId, qty: partial && i === 0 ? Math.max(0.5, Math.floor(l.qty / 2)) : l.qty })).filter((x) => x.qty > 0));
        if (partial && off < -2) { // the remainder arrives a day later, one transfer is left short
          const t2 = d.transfers.find((x) => x.id === t.id)!;
          if (chance(0.5)) receiveTransfer(d, cx(at(off + 1, 8, 20), 'U7'), t.id, t2.lines.map((l) => ({ productId: l.productId, qty: l.qty - l.receivedQty })).filter((x) => x.qty > 0));
          else closeTransferShort(d, cx(at(off + 1, 8, 20), 'U7'), t.id, 'Carton damaged in transit — written off');
        }
      });
    }
  }

  function payDueSuppliers(off: number) {
    for (const x of [...dueInvoices]) {
      if (dayKey(x.due) > dayKey(at(off, 10))) continue;
      dueInvoices.splice(dueInvoices.indexOf(x), 1);
      safe('pay supplier', () => {
        const inv = d.apInvoices.find((i) => i.id === x.invoiceId)!;
        const open = r2(inv.amount - inv.paid - inv.creditNotes);
        if (open > 0.004) paySupplier(d, cx(at(off, 10, 5), 'U9'), { supplierId: x.supplierId, amount: open, method: 'transfer', allocations: [{ invoiceId: inv.id, amount: open }] });
      });
    }
  }

  // ---------- orders
  const canFulfill = (wh: ID, lines: NewOrderLine[]) => {
    const need: Record<ID, number> = {};
    for (const l of lines) {
      const p = P(l.productId);
      if (p.kind === 'menu') {
        const bom = bomForProduct(d, p.id);
        const v = bom && versionAt(bom, nowIso);
        if (!v) return false;
        const mods = resolveModifiers(p, l.modifiers).map((m) => m.opt);
        const n: Record<ID, number> = {};
        for (const c of v.components) n[c.productId] = (n[c.productId] || 0) + (c.qty * l.qty) / v.yieldQty;
        for (const m of mods) {
          if (m.replace && n[m.replace.from] != null) { n[m.replace.to] = (n[m.replace.to] || 0) + n[m.replace.from]; delete n[m.replace.from]; }
          for (const a of m.add ?? []) n[a.productId] = (n[a.productId] || 0) + a.qty * l.qty;
        }
        for (const [k, q] of Object.entries(n)) need[k] = (need[k] || 0) + q;
      } else need[l.productId] = (need[l.productId] || 0) + l.qty;
    }
    return Object.entries(need).every(([pid, q]) => onHand(d, wh, pid) - (reservedMap(d)[bkey(wh, pid)] || 0) >= q + 0.001);
  };

  const drinkW = ['D03', 'D03', 'D03', 'D04', 'D04', 'D04', 'D02', 'D02', 'D02', 'D01', 'D05', 'D05', 'D06', 'D06', 'D07'];
  const drinkLine = (): NewOrderLine => {
    const id = pick(drinkW);
    const p = P(id);
    const mods: { group: string; option: string }[] = [];
    if (p.modifiers?.some((m) => m.name === 'Sweetness') && chance(0.4)) mods.push({ group: 'Sweetness', option: pick(['Less sweet', 'Normal', 'Extra sweet']) });
    if (p.modifiers?.some((m) => m.name === 'Extra') && chance(0.12)) mods.push({ group: 'Extra', option: 'Extra shot' });
    if (p.modifiers?.some((m) => m.name === 'Milk') && chance(0.14)) mods.push({ group: 'Milk', option: 'Oat milk' });
    return { productId: id, qty: chance(0.12) ? 2 : 1, modifiers: mods, note: chance(0.03) ? 'less ice' : undefined };
  };
  const foodLine = (): NewOrderLine => ({ productId: pick(['FD1', 'FD1', 'FD2', 'FD3']), qty: 1, modifiers: chance(0.3) ? [{ group: 'Serving', option: 'Warmed' }] : [] });
  const retailLine = (): NewOrderLine => ({ productId: pick(['F02', 'F02', 'F04', 'R03', 'R03', 'R04', 'R07', 'F03', 'R02']), qty: 1 });
  const members = () => d.customers.filter((c) => c.group !== 'wholesale');
  const wholesalers = () => d.customers.filter((c) => c.group === 'wholesale');
  let idemN = 0;

  const progress = (orderId: ID, createdAt: Date, off: number) => {
    const o = d.orders.find((x) => x.id === orderId);
    if (!o || o.channel === 'POS') return;
    const flow = FLOWS[CHANNELS[o.channel].flow];
    const age = -off;
    let target: OrderStatus;
    if (age >= 3) target = 'completed';
    else if (age >= 1) target = chance(0.7) ? 'completed' : pick(flow.filter((s) => s !== 'completed' && s !== 'new'));
    else target = pick(flow.slice(0, Math.max(2, flow.length - 2)));
    if (age >= 3 && o.channel === 'LINE' && chance(0.035)) { safe('cancel', () => cancelOrder(d, cx(addDays(createdAt, 0), 'U2'), orderId, 'Customer changed their mind')); return; }
    const steps = CHANNELS[o.channel].flow === 'food' ? [10, 28, 45] : [150, 420, 1500, 3200];
    let i = 0;
    while (o.status !== target) {
      const nxt = nextStatuses(o)[0];
      if (!nxt) break;
      const t = new Date(createdAt.getTime() + steps[Math.min(i, steps.length - 1)] * 60000);
      if (t.getTime() > now.getTime() - 120000) break;
      safe('advance', () => advanceOrder(d, { now: t.toISOString(), userId: 'U7', seed: true }, orderId));
      if (o.status === nxt) i++; else break;
      if (nxt === target) break;
    }
  };

  const placeOrder = (off: number, t: Date, kind: ChannelCode | 'POS2') => {
    const c = cx(t, kind === 'POS2' ? 'U4' : 'U3');
    const created = new Date(c.now);
    if (kind === 'POS' || kind === 'POS2') {
      const branch = kind === 'POS' ? 'B1' : 'B2';
      const wh = kind === 'POS' ? 'W1' : 'W2';
      const lines: NewOrderLine[] = [];
      const n = 1 + (chance(0.38) ? 1 : 0) + (chance(0.12) ? 1 : 0);
      for (let i = 0; i < n; i++) { const r = rnd(); lines.push(r < 0.7 ? drinkLine() : r < 0.9 && branch === 'B1' ? foodLine() : retailLine()); }
      if (chance(0.06)) lines.push({ productId: 'D03', qty: 1 }, { productId: 'FD1', qty: 1 });
      if (!canFulfill(wh, lines)) return;
      const member = chance(0.36) ? pick(members()) : undefined;
      const m = rnd();
      safe('pos order', () => {
        const id = createOrder(d, c, {
          channel: 'POS', branchId: branch, customerId: member?.id, lines, orderType: chance(0.55) && branch === 'B1' ? 'dine_in' : 'takeaway',
          tableNo: undefined, payments: [{ method: m < 0.36 ? 'cash' : m < 0.78 ? 'qr' : m < 0.97 ? 'card' : 'other', amount: 1e6 }],
          promoCode: member && chance(0.07) ? 'WELCOME50' : undefined, idempotencyKey: `seed-${++idemN}`,
        });
        void id;
      });
      return;
    }
    if (kind === 'LINE') {
      const whole = chance(0.4);
      const cust = whole ? pick(wholesalers()) : pick(members());
      const lines: NewOrderLine[] = whole
        ? [{ productId: 'F02', qty: int(8, 24) }, ...(chance(0.6) ? [{ productId: 'F03', qty: int(4, 12) }] : []), ...(chance(0.5) ? [{ productId: 'F04', qty: int(6, 24) }] : []), ...(chance(0.3) ? [{ productId: 'R05', qty: int(2, 6) }] : [])]
        : Array.from({ length: int(1, 3) }, () => ({ productId: pick(['F02', 'F03', 'F04', 'R01', 'R02', 'R05', 'R06']), qty: int(1, 3) }));
      if (!canFulfill('W3', lines)) return;
      if (whole && cust.creditLimit - customerOutstanding(d, cust.id) < 9500) return;
      safe('line order', () => {
        const id = createOrder(d, c, { channel: 'LINE', branchId: 'B3', customerId: cust.id, lines, payLater: whole, idempotencyKey: `seed-${++idemN}`, shipping: { recipient: cust.name, address: cust.address ?? 'Bangkok', carrier: pick(['Flash', 'Kerry', 'J&T']) } });
        progress(id, created, off);
        const o = d.orders.find((x) => x.id === id)!;
        if (!whole && o.status !== 'cancelled') {
          // retail customers pay by bank transfer; most are verified quickly
          if (-off >= 1 && chance(0.9)) createReceipt(d, { ...c, now: new Date(created.getTime() + 3 * 3600000).toISOString(), userId: 'U9' }, { customerId: cust.id, amount: o.total, method: 'transfer', reference: `SCB${int(100000, 999999)}`, allocations: [{ orderId: id, amount: o.total }] });
        }
      });
      return;
    }
    // marketplace & delivery imports
    const mk = kind as ChannelCode;
    const maps = d.mappings.filter((x) => x.channel === mk && x.productId);
    const nLines = mk === 'LINEMAN' ? int(1, 4) : int(1, 2);
    const lines = Array.from({ length: nLines }, () => {
      const m = pick(maps);
      const p = P(m.productId!);
      return { sku: m.externalSku, name: m.externalName, qty: mk === 'LINEMAN' ? (chance(0.25) ? 2 : 1) : chance(0.2) ? 2 : 1, price: p.channelPrices[mk] ?? p.price };
    });
    const wh = mk === 'LINEMAN' ? 'W1' : 'W3';
    if (!canFulfill(wh, lines.map((l) => ({ productId: maps.find((m) => m.externalSku === l.sku)!.productId!, qty: l.qty })))) return;
    const prefix = { SHOPEE: 'SP', LAZADA: 'LZ', TIKTOK: 'TT', LINEMAN: 'LM' }[mk as 'SHOPEE'];
    const extId = `${prefix}${String(2611000000 + int(100000, 999999) + off * 7)}`;
    safe('import', () => {
      const res = importExternalOrder(d, { ...c, userId: 'U1' }, mk, { externalId: extId, createdAt: c.now, buyer: `${pick(['Som', 'Nok', 'Ploy', 'Beam', 'Fern', 'Tan'])}***`, lines, voucher: chance(0.25) ? pick([10, 20, 30, 50]) : 0, raw: { order_sn: extId, items: lines, status: 'READY_TO_SHIP' } }, 'sync');
      if (res !== 'imported') return;
      const o = d.orders.find((x) => x.externalId === extId && x.channel === mk)!;
      progress(o.id, created, off);
    });
  };

  // ---------- main daily loop
  const wholesalePay = (off: number) => {
    for (const cust of wholesalers()) {
      const outs = outstandingOrders(d, cust.id);
      if (!outs.length) continue;
      if (['C003', 'C006'].includes(cust.id)) continue; // slow payers: keep some invoices overdue for the aging demo
      const oldest = outs[0].order;
      const ageDays = Math.floor((at(off, 12).getTime() - new Date(oldest.createdAt).getTime()) / 86400000);
      if (ageDays >= cust.creditDays - 2 + int(0, 6)) {
        const total = outs.reduce((s, x) => s + x.balance, 0);
        const amt = r2(chance(0.55) ? total : Math.max(oldest.total * 0.6, total * 0.5));
        safe('wholesale pay', () => createReceipt(d, cx(at(off, 14, 20), 'U9'), { customerId: cust.id, amount: Math.min(amt, total), method: 'transfer', reference: `KBank${int(1000, 9999)}`, allocations: 'fifo' }));
      }
    }
  };
  const settle = (off: number) => {
    for (const ch of ['SHOPEE', 'LAZADA', 'TIKTOK', 'LINEMAN'] as ChannelCode[]) {
      const acct = d.channelAccounts.find((a) => a.channel === ch)!;
      const cutoff = addDays(at(off, 9), -acct.settlementDays).getTime();
      const orders = settleable(d, ch).filter((o) => new Date(o.createdAt).getTime() <= cutoff);
      if (orders.length < 2) continue;
      safe('settle', () => {
        const c = cx(at(off, 11), 'U9');
        const est = { commission: orders.reduce((s, o) => s + o.fees.commission, 0), paymentFee: orders.reduce((s, o) => s + o.fees.paymentFee, 0), shippingSubsidy: orders.reduce((s, o) => s + o.fees.shippingSubsidy, 0) };
        const f = 0.97 + rnd() * 0.08;
        const sid = createSettlement(d, c, { channel: ch, orderIds: orders.map((o) => o.id), actual: { commission: r2(est.commission * f), paymentFee: r2(est.paymentFee * (0.99 + rnd() * 0.03)), shippingSubsidy: r2(est.shippingSubsidy * (0.9 + rnd() * 0.3)) } });
        const st = d.settlements.find((x) => x.id === sid)!;
        receiveSettlement(d, { ...c, now: at(off, 15).toISOString() }, sid, chance(0.2) ? r2(st.net - pick([12, 35, 60])) : st.net);
      });
    }
  };
  const doReturns = (off: number) => {
    if (off > -3) return;
    const cands = d.orders.filter((o) => o.status === 'completed' && o.channel !== 'POS' && o.channel !== 'LINEMAN' && !o.creditNoted && dayKey(o.createdAt) === dayKey(at(off - 3, 12)));
    for (const o of cands) {
      if (!chance(0.07)) continue;
      safe('return', () => returnOrder(d, cx(at(off, 16), 'U2'), { orderId: o.id, lines: [{ lineId: o.lines[0].id, qty: 1, restock: chance(0.7) }], reason: pick(['Damaged on arrival', 'Wrong item', 'Customer changed mind']), refund: o.collectedBy === 'platform' ? 'platform' : o.collectedBy === 'merchant' ? 'transfer' : 'none' }));
    }
  };
  const eventPicks = (off: number) => {
    const ev = d.events.find((e) => e.id === e1)!;
    if (ev.status !== 'active') return;
    const cs = new Set(d.entitlements.filter((e) => e.eventId === e1 && e.status === 'available').map((e) => e.customerId));
    for (const cid of cs) {
      if (!chance(0.55)) continue;
      for (let tries = 0; tries < 8; tries++) {
        try { claimNumber(d, cx(at(off, int(18, 21)), 'U1'), { eventId: e1, boardId: pick(ev.boards).id, number: int(0, 99), customerId: cid, confirm: true }); break; } catch { /* number taken → try another */ }
      }
    }
  };

  const mem = members();
  for (let off = -SEED_DAYS; off <= 0; off++) {
    const day = at(off, 12);
    const dow = day.getDay();
    const dom = day.getDate();
    replenish(off);
    receivePending(off);
    payDueSuppliers(off);
    // overheads
    if (dom === 1) safe('rent', () => addExpense(d, cx(at(off, 9), 'U9'), { date: cx(at(off, 9)).now, account: '6200', vendor: 'Landlord – 3 sites', amount: 25000, paidFrom: 'bank', note: 'Monthly rent' }));
    if (dom === 5) safe('util', () => addExpense(d, cx(at(off, 9), 'U9'), { date: cx(at(off, 9)).now, account: '6210', vendor: 'MEA / MWA', amount: 6100, paidFrom: 'bank' }));
    if (dom === 10) safe('bank', () => addExpense(d, cx(at(off, 9), 'U9'), { date: cx(at(off, 9)).now, account: '6400', vendor: 'Bank charges', amount: 420, paidFrom: 'bank' }));
    if (dow === 5) safe('staff', () => addExpense(d, cx(at(off, 17), 'U9'), { date: cx(at(off, 17)).now, account: '6220', vendor: 'Part-time staff', amount: 6500, paidFrom: 'cash' }));
    if (dow === 3) safe('mkt', () => addExpense(d, cx(at(off, 11), 'U10'), { date: cx(at(off, 11)).now, account: '6130', vendor: 'Meta Ads', amount: 2140, vat: 140, paidFrom: 'bank', note: 'Instagram/LINE ads' }));
    if (off === -13) { setEventStatus(d, cx(at(off, 9)), e1, 'active'); }
    if (off === -SEED_DAYS + 2) { for (let i = 0; i < 26; i++) grantEntitlements(d, cx(at(off, 12)), { eventId: e0, customerId: pick(mem).id, count: 1 }); }
    if (off === -SEED_DAYS + 3) {
      const ev0 = d.events.find((e) => e.id === e0)!;
      for (const en of d.entitlements.filter((e) => e.eventId === e0)) { for (let t = 0; t < 6; t++) { try { claimNumber(d, cx(at(off, int(10, 20))), { eventId: e0, boardId: pick(ev0.boards).id, number: int(0, 99), customerId: en.customerId, entitlementId: en.id }); break; } catch { /* taken */ } } }
    }
    if (off === -14) {
      const ev0 = d.events.find((e) => e.id === e0)!;
      for (const b of ev0.boards) { const s = d.selections.find((x) => x.eventId === e0 && x.boardId === b.id && x.status === 'confirmed'); if (s) recordWinner(d, cx(at(off, 15)), { eventId: e0, boardId: b.id, number: s.number, prize: b.id.endsWith('B1') ? 'Gold bean hamper ฿1,500' : b.id.endsWith('B2') ? 'V60 starter set' : '฿500 café voucher' }); }
      setEventStatus(d, cx(at(off, 15)), e0, 'closed');
    }

    const weekend = dow === 0 || dow === 6;
    const hrs = (lo: number, hi: number) => { const h = int(lo, hi); return at(off, h, int(0, 59)); };
    const todayLimit = off === 0 ? Math.max(0, Math.min(20, now.getHours() - 1)) : 20;
    const counts: [ChannelCode | 'POS2', number][] = [
      ['POS', int(12, 17) + (weekend ? 4 : 0)], ['POS2', int(4, 7) + (weekend ? 2 : 0)], ['LINE', int(2, 4)], ['SHOPEE', int(2, 4)], ['LAZADA', int(1, 3)], ['TIKTOK', int(1, 3)], ['LINEMAN', int(3, 6) + (weekend ? 1 : 0)],
    ];
    const queue: { t: Date; k: ChannelCode | 'POS2' }[] = [];
    for (const [k, n] of counts) for (let i = 0; i < n; i++) {
      if (off === 0 && todayLimit < 8) continue;
      queue.push({ t: hrs(k === 'LINEMAN' ? 10 : 8, Math.max(9, off === 0 ? todayLimit : k === 'POS' || k === 'POS2' ? 19 : 21)), k });
    }
    queue.sort((a, b) => a.t.getTime() - b.t.getTime());
    for (const q of queue) { if (q.t.getTime() < now.getTime() - 120000) placeOrder(off, q.t, q.k); }

    wholesalePay(off);
    if (dow === 1 || off === 0) settle(off);
    doReturns(off);
    if (off >= -12) eventPicks(off);
    // loyalty redemptions
    if (off % 3 === 0 && off < 0) {
      for (let i = 0; i < 2; i++) {
        const cust = pick(mem);
        const afford = d.rewards.filter((r) => r.active && (r.stock == null || r.stock > 0) && r.cost <= pointsBalance(d, cust.id));
        if (afford.length) safe('redeem', () => redeemReward(d, cx(at(off, 15), 'U3'), { customerId: cust.id, rewardId: pick(afford).id, idempotencyKey: `seed-r${off}-${i}` }));
      }
    }
    // shrinkage / waste
    if (off % 4 === 0 && off < 0) safe('waste', () => adjustStock(d, cx(at(off, 21), 'U5'), pick([{ productId: 'M03', warehouseId: 'W1', qty: -1.5, reason: 'Expired milk', kind: 'waste' as const }, { productId: 'M09', warehouseId: 'W1', qty: -3, reason: 'Freezer thaw', kind: 'waste' as const }, { productId: 'F04', warehouseId: 'W1', qty: -1, reason: 'Bottle cracked', kind: 'waste' as const }])));
    if (off === -10) safe('points', () => adjustPoints(d, cx(at(off, 10), 'U10'), mem[2].id, 100, 'Birthday gift'));
    if (off === -5) safe('count', () => { const id = startCount(d, cx(at(off, 7), 'U7'), 'W3'); const cnt = d.counts.find((c) => c.id === id)!; const counted: Record<ID, number> = {}; for (const l of cnt.lines) counted[l.productId] = l.productId === 'F02' ? Math.max(0, l.systemQty - 1) : l.productId === 'M01' ? Math.max(0, l.systemQty - 0.4) : l.systemQty; postCount(d, cx(at(off, 8), 'U7'), id, counted); });
  }

  // ---------- state left deliberately "in flight" so the demo has work to do
  const lateCtx = cx(now, 'U1');
  // a statement imported from Shopee but not yet received
  safe('pending settlement', () => {
    for (const ch of ['SHOPEE', 'LINEMAN'] as ChannelCode[]) {
      const os = settleable(d, ch);
      if (os.length >= 2) createSettlement(d, lateCtx, { channel: ch, orderIds: os.slice(0, Math.min(os.length, 6)).map((o) => o.id) });
    }
  });
  // an order that arrived with an unmapped SKU → sits in the error queue until someone maps it
  safe('unmapped order', () => { importExternalOrder(d, { ...lateCtx, now: new Date(now.getTime() - 35 * 60000).toISOString() }, 'SHOPEE', { externalId: 'SP2611999777', createdAt: new Date(now.getTime() - 35 * 60000).toISOString(), buyer: 'Fern***', lines: [{ sku: 'SPE-GIFTSET', name: 'Gift set (beans + mug) — new listing', qty: 1, price: 499 }, { sku: 'SPE-F02', name: 'Sabaidee House Blend 250 g', qty: 1, price: 209 }], raw: { order_sn: 'SP2611999777', status: 'READY_TO_SHIP' } }, 'sync'); });
  // payment slips waiting for review
  const alloc = allocatedMap(d);
  const unpaid = d.orders.filter((o) => o.channel === 'LINE' && o.customerId && o.status !== 'cancelled' && orderBalance(o, alloc[o.id] || 0) > 0 && d.customers.find((c) => c.id === o.customerId)!.group !== 'wholesale').slice(-4);
  unpaid.forEach((o, i) => {
    safe('slip', () => {
      const ref = `SCB${int(100000, 999999)}`;
      const mediaId = `MD-S${i + 1}`;
      const amount = o.total;
      d.media.push({ id: mediaId, kind: 'payment_slip', name: `slip_${ref}.svg`, mime: 'image/svg+xml', size: 2200, checksum: `demo${i}${ref}`, status: 'available', private: true, linkedType: 'slip', linkedId: undefined, uploadedBy: o.customerId!, createdAt: lateCtx.now, variants: [], dataUrl: slipSvg(amount, ref, d.customers.find((c) => c.id === o.customerId)!.name), scanNote: 'Demo placeholder (generated)' });
      const sid = submitSlip(d, { ...lateCtx, now: new Date(now.getTime() - (i + 1) * 40 * 60000).toISOString() }, { customerId: o.customerId!, amount: i === 3 ? amount - 50 : amount, orderIds: [o.id], reference: ref, mediaId, checksum: `demo${i}${ref}` });
      if (i === 3) d.slips.find((s) => s.id === sid)!.note = 'Customer says transfer fee was deducted';
    });
  });
  safe('rejected slip', () => {
    const cust = mem[4];
    const sid = submitSlip(d, { ...lateCtx, now: addDays(now, -2).toISOString() }, { customerId: cust.id, amount: 450, reference: 'KBANK-OLD', checksum: 'demo-rej' });
    rejectSlip(d, { ...lateCtx, now: addDays(now, -2).toISOString(), userId: 'U9' }, sid, 'Amount does not match any open order');
  });
  // two staff-entered sales to demonstrate live printing, with a few jobs left queued/failed
  safe('print demo', () => {
    const c: Ctx = { now: new Date(now.getTime() - 25 * 60000).toISOString(), userId: 'U3', seed: false };
    const lines = [{ productId: 'D03', qty: 1 }, { productId: 'FD1', qty: 1 }];
    if (canFulfill('W1', lines)) createOrder(d, c, { channel: 'POS', branchId: 'B1', lines, orderType: 'dine_in', tableNo: '4', payments: [{ method: 'qr', amount: 1e6 }], idempotencyKey: 'seed-print-1' });
    if (canFulfill('W2', [{ productId: 'D04', qty: 2 }])) createOrder(d, { ...c, userId: 'U4', now: new Date(now.getTime() - 12 * 60000).toISOString() }, { channel: 'POS', branchId: 'B2', lines: [{ productId: 'D04', qty: 2 }], payments: [{ method: 'cash', amount: 1e6 }], idempotencyKey: 'seed-print-2' });
    processPrintQueue(d, { ...c, now: new Date(now.getTime() - 5 * 60000).toISOString() });
  });
  // a few shortages so the low-stock alerts have something to show
  safe('low stock demo', () => {
    const c = { ...lateCtx, now: new Date(now.getTime() - 3 * 60000).toISOString(), userId: 'U5' };
    const shrink = (pid: ID, wh: ID, to: number, reason: string) => { const bal = onHand(d, wh, pid); if (bal > to) adjustStock(d, c, { productId: pid, warehouseId: wh, qty: -(bal - to), reason, kind: 'adjust' }); };
    shrink('M03', 'W1', 4, 'Cycle count: fridge door left open overnight');
    shrink('R04', 'W2', 6, 'Cycle count correction');
    shrink('K05', 'W1', 90, 'Cup carton found damaged');
  });
  // governance: close last month, mark old bank lines reconciled
  const eom = startOfDay(now);
  eom.setDate(0);
  closePeriod(d, lateCtx, dayKey(eom));
  const cut = dayKey(addDays(now, -9));
  for (const j of d.journals) j.lines.forEach((l, i) => { if ((l.account === '1110' || l.account === '1100') && dayKey(j.date) < cut) d.reconciled[`${j.id}:${i}`] = true; });
  audit(d, lateCtx, 'seed', 'system', undefined, 'Demo data generated', 'info');
  d.meta.currentUserId = 'U1';
  d._seedErrors = errors;
  return d;
}

function slipSvg(amount: number, ref: string, name: string): string {
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="300" height="420" viewBox="0 0 300 420"><rect width="300" height="420" rx="16" fill="#f6f7f9"/><rect width="300" height="72" rx="16" fill="#1c5cab"/><rect y="40" width="300" height="32" fill="#1c5cab"/><text x="150" y="44" text-anchor="middle" font-family="Arial" font-size="20" font-weight="700" fill="#fff">Transfer successful</text><text x="150" y="104" text-anchor="middle" font-family="Arial" font-size="12" fill="#666">Demo placeholder slip</text><text x="150" y="168" text-anchor="middle" font-family="Arial" font-size="34" font-weight="700" fill="#111">฿${amount.toLocaleString('en-US', { minimumFractionDigits: 2 })}</text><line x1="24" y1="200" x2="276" y2="200" stroke="#ddd"/><text x="24" y="232" font-family="Arial" font-size="12" fill="#888">From</text><text x="24" y="252" font-family="Arial" font-size="15" fill="#111">${name}</text><text x="24" y="288" font-family="Arial" font-size="12" fill="#888">To</text><text x="24" y="308" font-family="Arial" font-size="15" fill="#111">Sabaidee Roasters Co., Ltd.</text><text x="24" y="344" font-family="Arial" font-size="12" fill="#888">Reference</text><text x="24" y="364" font-family="Arial" font-size="15" fill="#111">${ref}</text><rect x="214" y="332" width="62" height="62" fill="none" stroke="#111" stroke-width="2"/><path d="M222 340h16v16h-16zM252 340h16v16h-16zM222 370h16v16h-16zM246 364h8v8h-8zM260 378h8v8h-8z" fill="#111"/></svg>`;
  return 'data:image/svg+xml;utf8,' + encodeURIComponent(svg);
}
